<script setup lang="ts">
import{computed}from'vue';import{t}from'./i18n';import{conversionDefaults,type ConversionOptions}from'../../../packages/contracts';
const props=defineProps<{modelValue?:ConversionOptions}>(),emit=defineEmits<{'update:modelValue':[value:ConversionOptions]}>();
const options=computed(()=>({...conversionDefaults,...props.modelValue}));
function update(key:keyof ConversionOptions,event:Event){const value=(event.target as HTMLSelectElement).value;emit('update:modelValue',{...options.value,[key]:key==='quality'?value:Number(value)} as ConversionOptions);}
</script>
<template><div class="conversion-controls"><label>{{ t('conversionQuality') }}<select :aria-label="t('conversionQuality')" :value="options.quality" @change="update('quality',$event)"><option v-for="quality in ['auto','high','balanced','small']" :key="quality" :value="quality">{{ t('conversionQuality_' + quality) }}</option></select></label><label>{{ t('conversionResolution') }}<select :aria-label="t('conversionResolution')" :value="options.maxHeight" @change="update('maxHeight',$event)"><option :value="0">{{ t('conversionOriginal') }}</option><option v-for="height in [1080,720,480]" :key="height" :value="height">{{ height }}p</option></select></label><label>{{ t('conversionAudio') }}<select :aria-label="t('conversionAudio')" :value="options.audioKbps" @change="update('audioKbps',$event)"><option :value="0">{{ t('conversionAudioAuto') }}</option><option v-for="rate in [128,192,256]" :key="rate" :value="rate">{{ rate }} kb/s</option></select></label><p class="setting-hint">{{ t('conversionOptionsHint') }}</p></div></template>
<style scoped>.conversion-controls{display:grid;gap:12px;margin-block:16px}.conversion-controls label{min-width:0}.conversion-controls select{width:100%}.conversion-controls p{margin:0;line-height:1.65}</style>
